import { readFileSync } from 'node:fs';
import path from 'node:path';
import { GLB } from './js/glb.mjs';
import { Game } from './js/game.mjs';
function loadGlb(n){const g=new GLB(n);g.raw=new Uint8Array(readFileSync(path.resolve('data',n)));return g.parse();}
const glb1=loadGlb('FILE0001.GLB'), glb0=loadGlb('FILE0000.GLB');
const game=new Game(glb1,glb0,{play(){},sfxCount:0,state:'running'});
const clear=()=>{game.input.left=game.input.right=game.input.up=game.input.down=game.input.fire=false;};
const run=(n,inp)=>{ for(let i=0;i<n;i++){clear(); Object.assign(game.input,inp); game.frame();} };
const P=()=>[game.player_cx, game.player_cy];
let p0=P();
run(20,{up:true});  let p1=P();
run(20,{});         let p2=P();
run(20,{down:true});let p3=P();
run(20,{});         let p4=P();
run(20,{left:true}); let p5=P();
run(20,{});         let p6=P();
run(20,{right:true});let p7=P();
run(20,{});         let p8=P();
console.log('start',p0,'up',p1,'settle',p2,'down',p3,'settle',p4,'left',p5,'settle',p6,'right',p7,'settle',p8);
console.log('settle drift (must all be 0):', p2[0]-p1[0], p2[1]-p1[1], p4[0]-p3[0], p4[1]-p3[1], p6[0]-p5[0], p6[1]-p5[1], p8[0]-p7[0], p8[1]-p7[1]);
console.log('up moves y down? ', p1[1]<p0[1], '| down moves y up?', p3[1]>p1[1], '| left x?', p5[0]<p4[0], '| right x?', p7[0]>p6[0]);
console.log('x drift during vertical (must be 0):', p1[0]-p0[0], p3[0]-p1[0], '| y drift during horizontal (must be 0):', p5[1]-p4[1], p7[1]-p6[1]);
// firing: player shot owner + movement
clear(); game.input.fire=true; game.frame(); game.frame(); game.input.fire=false;
const shots=game.shots.map(s=>[s.x,s.y]);
console.log('shots after 2 frames:', JSON.stringify(shots));
const y0=shots[0][1];
for(let i=0;i<10;i++) game.frame();
console.log('shot y after 10 frames:', game.shots.map(s=>s.y), '(should be <', y0,')');
" 2>&1

