import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import os from 'node:os';
import fs from 'node:fs';

const PORT = 8765;
function findChrome() {
  const env = process.platform === 'win32'
    ? (process.env.LOCALAPPDATA || path.join(os.homedir(), 'AppData', 'Local'))
    : (process.env.HOME || os.homedir());
  const base = path.join(env, 'ms-playwright');
  const dirs = fs.readdirSync(base).filter((d) => d.startsWith('chromium-') && !d.includes('headless_shell')).sort().reverse();
  for (const d of dirs) for (const sub of ['chrome-win64', 'chrome-linux', 'chrome-mac']) {
    const exe = path.join(base, d, sub, process.platform === 'win32' ? 'chrome.exe' : 'chrome');
    if (fs.existsSync(exe)) return exe;
  }
  return null;
}
const chrome = findChrome();
const dbgPort = 9441 + Math.floor(Math.random() * 50);
const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'raptor-m2-'));
const proc = spawn(chrome, ['--headless=new', `--remote-debugging-port=${dbgPort}`, `--user-data-dir=${profile}`, '--disable-gpu', '--no-first-run', 'about:blank'], { stdio: 'ignore' });

let failures = 0;
const check = (c, m) => { console.log((c ? 'ok  : ' : 'FAIL: ') + m); if (!c) failures++; };
const getJson = async (url, method = 'GET') => (await fetch(url, { method })).json();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

class CDP {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); }
  static async connect(url) {
    const ws = new WebSocket(url);
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
    const c = new CDP(ws);
    ws.onmessage = (m) => {
      const msg = JSON.parse(m.data);
      if (msg.id && c.pending.has(msg.id)) { const p = c.pending.get(msg.id); c.pending.delete(msg.id); msg.error ? p.rej(new Error(msg.error.message)) : p.res(msg.result); }
    };
    return c;
  }
  send(method, params = {}) { const id = ++this.id; this.ws.send(JSON.stringify({ id, method, params })); return new Promise((res, rej) => this.pending.set(id, { res, rej })); }
  close() { try { this.ws.close(); } catch { /* */ } }
}

try {
  for (let i = 0; i < 50; i++) { try { const l = await getJson(`http://127.0.0.1:${dbgPort}/json/list`); if (l.length) break; } catch { /* */ } await sleep(200); }
  const target = await getJson(`http://127.0.0.1:${dbgPort}/json/new?http://127.0.0.1:${PORT}/`, 'PUT');
  const cdp = await CDP.connect(target.webSocketDebuggerUrl);
  await cdp.send('Page.enable'); await cdp.send('Runtime.enable');
  const evalJs = async (e) => (await cdp.send('Runtime.evaluate', { expression: e, returnByValue: true })).result.value;

  for (let i = 0; i < 120; i++) { if (await evalJs(`window.__raptor && window.__raptor.ready === true`).catch(() => false)) break; await sleep(250); }
  check(await evalJs(`window.__raptor.ready === true`), 'booted, ready true');

  const KC = { ArrowLeft: 37, ArrowRight: 39, ArrowUp: 38, ArrowDown: 40, ' ': 32 };
  const press = (t, k) => cdp.send('Input.dispatchKeyEvent', { type: t, key: k, code: k === ' ' ? 'Space' : k, windowsVirtualKeyCode: KC[k] });

  // --- all four arrow keys, one at a time ---
  const start = await evalJs(`JSON.parse(JSON.stringify(window.__raptor.player))`);
  await press('keyDown', 'ArrowUp'); await sleep(450); await press('keyUp', 'ArrowUp');
  const pUp = await evalJs(`JSON.parse(JSON.stringify(window.__raptor.player))`);
  await press('keyDown', 'ArrowDown'); await sleep(450); await press('keyUp', 'ArrowDown');
  const pDn = await evalJs(`JSON.parse(JSON.stringify(window.__raptor.player))`);
  await press('keyDown', 'ArrowLeft'); await sleep(450); await press('keyUp', 'ArrowLeft');
  const pLf = await evalJs(`JSON.parse(JSON.stringify(window.__raptor.player))`);
  await press('keyDown', 'ArrowRight'); await sleep(450); await press('keyUp', 'ArrowRight');
  const pRt = await evalJs(`JSON.parse(JSON.stringify(window.__raptor.player))`);
  console.log(`      player path: ${start.x},${start.y} -> up ${pUp.x},${pUp.y} -> down ${pDn.x},${pDn.y} -> left ${pLf.x},${pLf.y} -> right ${pRt.x},${pRt.y}`);
  check(pUp.y < start.y, `ArrowUp moves ship up (y ${start.y} -> ${pUp.y})`);
  check(pDn.y > pUp.y, `ArrowDown moves ship down (y ${pUp.y} -> ${pDn.y})`);
  check(pLf.x < pDn.x, `ArrowLeft moves ship left (x ${pDn.x} -> ${pLf.x})`);
  check(pRt.x > pLf.x, `ArrowRight moves ship right (x ${pLf.x} -> ${pRt.x})`);
  check(pUp.x === start.x && pLf.y === pDn.y, 'no axis drift (x fixed during up/down, y fixed during left/right)');

  // --- Space fires; projectiles live in __raptor and expire ---
  const s0 = await evalJs(`window.__raptor.projectiles.length`);
  await press('keyDown', ' '); await sleep(500);
  const mid = await evalJs(`JSON.parse(JSON.stringify(window.__raptor.projectiles))`);
  await press('keyUp', ' ');
  check(mid.length > s0, `Space spawns projectiles (${s0} -> ${mid.length})`);
  check(mid.every((p) => p.owner === 'player' && Number.isFinite(p.x) && Number.isFinite(p.y)), 'projectiles have owner + finite x/y');
  check(mid.some((p) => p.y < start.y), 'projectiles travel upward (y decreased)');
  // stop firing: existing projectiles fly off and the list drains
  await sleep(2500);
  const s1 = await evalJs(`window.__raptor.projectiles.length`);
  check(s1 < mid.length, `projectile list is live/drains after firing stops (${mid.length} -> ${s1})`);
  const sfx = await evalJs(`window.__raptor.audio.sfxCount`);
  check(sfx > 0, `fire SFX counted (${sfx})`);

  cdp.close();
} finally {
  proc.kill();
  try { fs.rmSync(profile, { recursive: true, force: true }); } catch { /* */ }
}
console.log(failures ? 'M2 CHECK FAILED' : 'M2 CHECK OK');
process.exit(failures ? 1 : 0);

